<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans;color:#173334;font-size:11px}h1{font-size:22px;color:#126e68;margin:0}h2{font-size:14px;margin:18px 0 6px}.muted{color:#657b7b}table{width:100%;border-collapse:collapse}th,td{padding:7px;border:1px solid #dce7e5;text-align:left}th{background:#e9f5f2}.red{color:#b42318;font-weight:bold}.amber{color:#a15c00;font-weight:bold}.green{color:#087443;font-weight:bold}.metric{display:inline-block;width:22%;padding:10px;margin:5px;background:#f2f8f7}</style></head><body><h1>RAHS Hospital Operations Executive Report</h1><p class="muted">Generated {{ $generatedAt->format('d M Y H:i') }}</p><div><span class="metric">Facilities<br><b>{{ $readiness->count() }}</b></span><span class="metric">Critical<br><b>{{ $readiness->where('status','red')->count() }}</b></span><span class="metric">Attention<br><b>{{ $readiness->where('status','amber')->count() }}</b></span><span class="metric">Ready<br><b>{{ $readiness->where('status','green')->count() }}</b></span></div><h2>Facility readiness</h2><table><thead><tr><th>Hospital</th><th>Island / Atoll</th><th>Status</th><th>Critical</th><th>Warnings</th></tr></thead><tbody>@foreach($readiness as $r)<tr><td>{{ $r['name'] }}</td><td>{{ $r['island'] }} / {{ $r['atoll'] }}</td><td class="{{ $r['status'] }}">{{ strtoupper($r['status']) }}</td><td>{{ $r['critical'] }}</td><td>{{ $r['warnings'] }}</td></tr>@endforeach</tbody></table><h2>Active emergencies</h2><table><tr><th>Hospital</th><th>Incident</th><th>Severity</th><th>Status</th><th>Created</th></tr>@foreach($incidents->whereIn('status',['active','acknowledged']) as $i)<tr><td>{{ $i->hospitalProfile?->hospitalContact?->hospital_name }}</td><td>{{ $i->title }}</td><td>{{ strtoupper($i->severity) }}</td><td>{{ $i->status }}</td><td>{{ $i->created_at?->format('d M Y') }}</td></tr>@endforeach</table><h2>Equipment and transport risks</h2><table><tr><th>Hospital</th><th>Type</th><th>Item</th><th>Status</th></tr>@foreach($faults->whereNotIn('status',['operational','retired']) as $f)<tr><td>{{ $f->hospitalProfile?->hospitalContact?->hospital_name }}</td><td>Equipment</td><td>{{ $f->equipment_name }}</td><td>{{ $f->status }}</td></tr>@endforeach @foreach($transport->where('status','!=','operational') as $a)<tr><td>{{ $a->hospitalProfile?->hospitalContact?->hospital_name }}</td><td>{{ ucfirst($a->type) }}</td><td>{{ $a->name }}</td><td>{{ $a->status }}</td></tr>@endforeach</table></body></html>
